export const glossary=[['amount of substance',"The number of moles, n, measured in mol."],['molar mass',"The mass of one mole, M, usually in g/mol."],['mole fraction',"A component’s moles divided by total moles: χᵢ = nᵢ/n_total."],['lone pair',"Two valence electrons not used in a bond in a Lewis structure."],['bonding / antibonding',"An orbital that strengthens a bond / an orbital that weakens it when occupied."],['bond order',"Half the difference between bonding and antibonding electron counts."],['bond length',"The equilibrium distance between two bonded nuclei."],['paramagnetic',"Having unpaired electrons and being attracted to a magnetic field."],['effusion',"Gas escaping through a tiny opening into a vacuum."],['mean free path',"The average distance a molecule travels between collisions."],['surroundings',"Everything outside the system being studied."],['heat released',"The positive magnitude of heat transferred out of the system."],['heat absorbed',"Heat transferred into the system; q is positive."],['constant volume',"A process at constant volume."],['constant pressure',"A process at constant pressure."],['reversible',"An ideal limiting process that can be reversed by an infinitesimal change."],['isothermal',"A process at constant temperature."],['enthalpy of formation',"The enthalpy change when one mole forms from its elements in their reference states."],['lattice dissociation',"The enthalpy required to separate one mole of an ionic solid into gaseous ions."],['reaction quotient',"Q: the product-to-reactant activity expression evaluated at the current composition."],['equilibrium yield',"The amount of product present when equilibrium is reached."],['conjugate base',"The species left when an acid donates one proton."],['negligible',"Small enough to ignore within a stated approximation."],['spontaneous',"Thermodynamically favourable under the stated conditions; not necessarily fast."],['estimate / calculate',"Find an approximate value / work out a numerical value."],['FALSE / NOT correct',"Select the statement that is false, not the one that is true."]];

